def load():
    """Gibt {Prefix: Hersteller} zurück (dekomprimiert)."""
    raw = _gz.decompress(_b64.b64decode(_B64)).decode('utf-8')
    t = {}
    for line in raw.splitlines():
        if '\t' in line:
            p, n = line.split('\t', 1)
            t[p] = n
    return t
